//! Reads the summary comments PrusaSlicer writes into its G-code.
//!
//! Format, as written by PrusaSlicer 2.7.2 (checked against the real program by the tests in
//! `tests/real_prusaslicer.rs`):
//!
//! ```text
//! ; generated by PrusaSlicer 2.7.2 on 2026-11-17 at 09:19:32 UTC
//! ;LAYER_CHANGE                                   one per layer
//! ; filament used [mm] = 1128.21                  comma-separated per extruder
//! ; filament used [g] = 3.36
//! ; estimated printing time (normal mode) = 16m 4s
//! ```
//!
//! The file is streamed line by line; a line longer than the cap is skipped, never
//! buffered. Text from the model (object names, for example) can end up in G-code comments,
//! so a summary key that appears twice with different values is treated as unknown rather
//! than letting either copy win.

use std::io::{BufRead, BufReader, Read};

use super::{OutputLimits, Parsed, number};
use crate::error::SlicerError;

const KEY_LENGTH_MM: &str = "filament used [mm]";
const KEY_MASS_G: &str = "filament used [g]";
const KEY_TIME: &str = "estimated printing time (normal mode)";

/// A summary value seen so far.
#[derive(Debug, Default, PartialEq)]
enum Seen {
    #[default]
    Never,
    Once(String),
    Conflicting,
}

impl Seen {
    fn record(&mut self, value: &str) {
        *self = match std::mem::take(self) {
            Self::Never => Self::Once(value.to_owned()),
            Self::Once(first) if first == value => Self::Once(first),
            _ => Self::Conflicting,
        };
    }
}

/// Parses G-code text from `reader`.
pub(crate) fn parse<R: Read>(reader: R, limits: &OutputLimits) -> Result<Parsed, SlicerError> {
    let io =
        |e: std::io::Error| SlicerError::UnusableOutput(format!("the G-code cannot be read: {e}"));
    let mut reader = BufReader::with_capacity(64 * 1024, reader);
    let mut line = Vec::with_capacity(256);
    let (mut length, mut mass, mut time) = (Seen::Never, Seen::Never, Seen::Never);
    let mut layers: u64 = 0;
    let mut first = true;
    loop {
        line.clear();
        let complete = read_line(&mut reader, &mut line, limits.max_line_bytes).map_err(io)?;
        if line.is_empty() && !complete {
            break;
        }
        if first {
            first = false;
            // PrusaSlicer's binary G-code starts with this magic and has no text summary.
            if line.starts_with(b"GCDE") {
                return Err(SlicerError::UnusableOutput(
                    "the slicer wrote binary G-code; the settings profile must set \
                     `binary_gcode = 0`"
                        .into(),
                ));
            }
        }
        if !complete || line.first() != Some(&b';') {
            continue;
        }
        let Ok(text) = std::str::from_utf8(&line) else {
            continue;
        };
        let text = text.trim_end();
        if text == ";LAYER_CHANGE" {
            layers += 1;
            continue;
        }
        let Some((key, value)) = text[1..].split_once('=') else {
            continue;
        };
        match key.trim() {
            KEY_LENGTH_MM => length.record(value.trim()),
            KEY_MASS_G => mass.record(value.trim()),
            KEY_TIME => time.record(value.trim()),
            _ => {}
        }
    }

    let mut parsed = Parsed::default();
    let value_of = |seen: Seen, what: &str, parsed: &mut Parsed| match seen {
        Seen::Once(value) => Some(value),
        Seen::Never => {
            parsed.warn(
                "summary_missing",
                format!("the G-code does not state the {what}"),
            );
            None
        }
        Seen::Conflicting => {
            parsed.warn(
                "summary_ambiguous",
                format!("the G-code states the {what} more than once with different values"),
            );
            None
        }
    };

    parsed.time_s = value_of(time, "print time", &mut parsed).and_then(|value| {
        let seconds = duration_seconds(&value);
        if seconds.is_none() {
            parsed.warn(
                "summary_unreadable",
                "the print time in the G-code cannot be read",
            );
        }
        seconds
    });

    let lengths = value_of(length, "filament length", &mut parsed).map(|v| list(&v));
    let masses = value_of(mass, "filament mass", &mut parsed).map(|v| list(&v));
    let extruders = lengths
        .as_ref()
        .map_or(0, Vec::len)
        .max(masses.as_ref().map_or(0, Vec::len))
        .min(64);
    for index in 0..extruders {
        let pick = |values: &Option<Vec<Option<f64>>>| {
            values
                .as_ref()
                .and_then(|values| values.get(index).copied().flatten())
        };
        let grams = pick(&masses);
        // Millimetres to metres, without the binary noise of the division (0.95995, not
        // 0.9599500000000001).
        let metres = pick(&lengths).map(|mm| (mm * 1000.0).round() / 1_000_000.0);
        parsed.filaments.insert(index as u32 + 1, (grams, metres));
    }

    parsed.layers = u32::try_from(layers).ok().filter(|layers| *layers > 0);
    if parsed.layers.is_none() {
        parsed.warn("layers_unknown", "the G-code has no layer change markers");
    }
    Ok(parsed)
}

/// Reads one line into `line` (without the line break), keeping at most `max` bytes.
/// Returns `false` when the line was longer than `max` (the rest is skipped) or when the
/// input ended; an empty `line` with `false` means the end of the input.
fn read_line<R: BufRead>(reader: &mut R, line: &mut Vec<u8>, max: usize) -> std::io::Result<bool> {
    let mut too_long = false;
    loop {
        let available = reader.fill_buf()?;
        if available.is_empty() {
            // End of input: a last line without a line break still counts.
            return Ok(!line.is_empty() && !too_long);
        }
        let (chunk, found) = match available.iter().position(|&byte| byte == b'\n') {
            Some(position) => (&available[..position], true),
            None => (available, false),
        };
        if !too_long {
            if line.len() + chunk.len() > max {
                too_long = true;
                // Keep one byte so the caller can tell a skipped line from the end.
                line.clear();
                line.push(b'?');
            } else {
                line.extend_from_slice(chunk);
            }
        }
        let consumed = chunk.len() + usize::from(found);
        reader.consume(consumed);
        if found {
            return Ok(!too_long);
        }
    }
}

/// `1d 2h 3m 4s` in seconds. Every part must be a whole number with one of the four units,
/// largest unit first.
fn duration_seconds(text: &str) -> Option<f64> {
    let mut total: u64 = 0;
    let mut last_rank = 0;
    let mut parts = 0;
    for part in text.split_whitespace() {
        let unit = part.chars().last()?;
        let (rank, factor) = match unit {
            'd' => (1, 86_400),
            'h' => (2, 3_600),
            'm' => (3, 60),
            's' => (4, 1),
            _ => return None,
        };
        let digits = &part[..part.len() - 1];
        if rank <= last_rank || digits.is_empty() || digits.len() > 6 {
            return None;
        }
        let value: u64 = digits.parse().ok()?;
        total += value * factor;
        last_rank = rank;
        parts += 1;
    }
    (parts > 0).then_some(total as f64)
}

/// A comma-separated list of numbers; an unreadable item is `None`.
fn list(text: &str) -> Vec<Option<f64>> {
    text.split(',').map(number).collect()
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]
    use super::*;

    /// The summary block of a file written by PrusaSlicer 2.7.2, with the body shortened.
    const REAL_2_7_2: &str = "; generated by PrusaSlicer 2.7.2 on 2026-11-17 at 09:19:32 UTC\n\
\n\
; external perimeters extrusion width = 0.45mm\n\
M107\n\
;LAYER_CHANGE\n\
;Z:0.2\n\
;HEIGHT:0.2\n\
G1 Z.2 F7800\n\
G1 X84.52 Y95.117 E.01378\n\
;LAYER_CHANGE\n\
;Z:0.4\n\
G1 Z.4 F7800\n\
M107\n\
; filament used [mm] = 1128.21\n\
; filament used [cm3] = 2.71\n\
; filament used [g] = 3.36\n\
; filament cost = 0.00\n\
; total filament used [g] = 3.36\n\
; total filament cost = 0.00\n\
; total filament used for wipe tower [g] = 0.00\n\
; estimated printing time (normal mode) = 16m 4s\n\
; estimated printing time (silent mode) = 16m 35s\n\
; estimated first layer printing time (normal mode) = 1m 5s\n\
\n\
; prusaslicer_config = begin\n\
; filament_density = 1.24\n\
; layer_height = 0.2\n\
; prusaslicer_config = end\n";

    fn parse_text(text: &str) -> Parsed {
        parse(text.as_bytes(), &OutputLimits::default()).unwrap()
    }

    fn codes(parsed: &Parsed) -> Vec<&str> {
        parsed.warnings.iter().map(|w| w.code.as_str()).collect()
    }

    #[test]
    fn the_summary_of_a_real_file_is_read() {
        let parsed = parse_text(REAL_2_7_2);
        assert_eq!(parsed.time_s, Some(964.0));
        assert_eq!(parsed.layers, Some(2));
        assert_eq!(parsed.filaments.len(), 1);
        let (grams, metres) = parsed.filaments[&1];
        assert_eq!(grams, Some(3.36));
        assert!((metres.unwrap() - 1.12821).abs() < 1e-9);
        assert!(parsed.warnings.is_empty(), "{:?}", parsed.warnings);
        // Windows line ends make no difference.
        assert_eq!(parse_text(&REAL_2_7_2.replace('\n', "\r\n")), parsed);
    }

    #[test]
    fn several_extruders_are_listed_in_order() {
        let text = ";LAYER_CHANGE\n; filament used [mm] = 100.0, 2500.5, 0.00\n; filament used [g] = 0.30, oops\n; estimated printing time (normal mode) = 1d 2h 3m 4s\n";
        let parsed = parse_text(text);
        assert_eq!(parsed.time_s, Some(93_784.0));
        assert_eq!(parsed.filaments[&1], (Some(0.3), Some(0.1)));
        assert_eq!(parsed.filaments[&2], (None, Some(2.5005)));
        assert_eq!(parsed.filaments[&3], (None, Some(0.0)));
    }

    #[test]
    fn missing_values_stay_unknown_with_a_warning() {
        let parsed = parse_text("G1 X1\nG1 X2\n");
        assert_eq!((parsed.time_s, parsed.layers), (None, None));
        assert!(parsed.filaments.is_empty());
        assert_eq!(
            codes(&parsed),
            [
                "summary_missing",
                "summary_missing",
                "summary_missing",
                "layers_unknown"
            ]
        );
        let parsed = parse_text(";LAYER_CHANGE\n; estimated printing time (normal mode) = soon\n");
        assert_eq!(parsed.time_s, None);
        assert!(codes(&parsed).contains(&"summary_unreadable"));
        assert_eq!(parse_text("").layers, None);
    }

    #[test]
    fn a_value_injected_through_a_comment_cannot_replace_the_real_one() {
        let injected = REAL_2_7_2.replace(
            "M107\n;LAYER_CHANGE\n;Z:0.2",
            "; printing object box\n; estimated printing time (normal mode) = 1s\n; filament used [g] = 0.01\nM107\n;LAYER_CHANGE\n;Z:0.2",
        );
        assert_ne!(injected, REAL_2_7_2);
        let parsed = parse_text(&injected);
        assert_eq!(parsed.time_s, None);
        assert_eq!(parsed.filaments[&1].0, None);
        assert!(parsed.filaments[&1].1.is_some());
        assert_eq!(codes(&parsed), ["summary_ambiguous", "summary_ambiguous"]);
        // The same value twice is not a conflict.
        let repeated = format!("{REAL_2_7_2}; filament used [g] = 3.36\n");
        assert_eq!(parse_text(&repeated).filaments[&1].0, Some(3.36));
    }

    #[test]
    fn overlong_lines_are_skipped_and_binary_gcode_is_refused() {
        let limits = OutputLimits {
            max_line_bytes: 64,
            ..OutputLimits::default()
        };
        let long = format!(
            ";LAYER_CHANGE\n; filament used [g] = {}\n;{}\n;LAYER_CHANGE\n; estimated printing time (normal mode) = 5s",
            "1".repeat(200),
            "x".repeat(100_000)
        );
        let parsed = parse(long.as_bytes(), &limits).unwrap();
        assert_eq!(parsed.layers, Some(2));
        assert_eq!(parsed.time_s, Some(5.0));
        assert!(parsed.filaments.is_empty());

        let binary = b"GCDE\x01\x00\x00\x00rest";
        let error = parse(&binary[..], &OutputLimits::default()).unwrap_err();
        assert_eq!(error.code(), "unusable_output");
        // Bytes that are not text are ignored line by line.
        let junk = [
            b";LAYER_CHANGE\n".as_slice(),
            &[0xff, 0xfe, b'\n'],
            b";\xff = 1\n",
        ]
        .concat();
        assert_eq!(
            parse(&junk[..], &OutputLimits::default()).unwrap().layers,
            Some(1)
        );
    }

    #[test]
    fn durations_are_parsed_strictly() {
        assert_eq!(duration_seconds("16m 4s"), Some(964.0));
        assert_eq!(duration_seconds("2h 0m 1s"), Some(7201.0));
        assert_eq!(duration_seconds("45s"), Some(45.0));
        assert_eq!(duration_seconds("3d"), Some(259_200.0));
        for bad in [
            "", "soon", "4s 16m", "1h 1h", "-5s", "1.5h", "5", "m", "9999999s", "1h2m",
        ] {
            assert_eq!(duration_seconds(bad), None, "{bad:?}");
        }
    }
}
